/**
 * Direct REST connection to chat.deepseek.com — bypasses the GenCoder
 * Chrome extension entirely. Speaks the same web-app protocol the browser
 * uses (Bearer token + DeepSeekHashV1 PoW + SSE completion stream).
 *
 * Why this exists: the extension path needs Chrome + a logged-in tab open
 * and pinned to one machine. This module lets a server-side process do the
 * same job with just a captured `auth_token` (from /api/v0/users/current).
 *
 * Status: experimental, gated. Default agent path stays on the bridge.
 *
 * Sequence per turn:
 *   1. POST /chat_session/create        (bearer only — no PoW required)
 *   2. POST /chat/create_pow_challenge  (bearer only — returns challenge)
 *   3. solve challenge in WASM          (~50–500 ms depending on difficulty)
 *   4. POST /chat/completion            (bearer + x-ds-pow-response, SSE)
 *
 * Steps 2–4 repeat per message; step 1 only on first turn of a session.
 *
 * The WASM module (sha3_wasm.wasm) is the same one DeepSeek's web app
 * loads. It exports `wasm_solve(retptr, chal, chal_len, prefix, prefix_len, difficulty)`
 * and we read the answer from the i64 written at retptr+8.
 */
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { createLogger } from "../../log/logger.js";

const log = createLogger("direct");

const BASE = "https://chat.deepseek.com/api/v0";
const DEFAULT_TIMEOUT_MS = 180_000;

// ── Error classes ─────────────────────────────────────────────────────────
// Distinct subtypes so callers can react: rotate token, back off, surface
// to UI, etc. Every message goes through `redact()` so a leaked token never
// ends up in a log line or thrown stack.
export class DirectError extends Error {
  constructor(message: string, public readonly cause?: unknown) {
    super(redact(message));
    this.name = "DirectError";
  }
}
export class DirectAuthError extends DirectError { constructor(m: string, c?: unknown) { super(m, c); this.name = "DirectAuthError"; } }
export class DirectRateLimitError extends DirectError { constructor(m: string, c?: unknown) { super(m, c); this.name = "DirectRateLimitError"; } }
export class DirectPowError extends DirectError { constructor(m: string, c?: unknown) { super(m, c); this.name = "DirectPowError"; } }
export class DirectNetworkError extends DirectError { constructor(m: string, c?: unknown) { super(m, c); this.name = "DirectNetworkError"; } }
export class DirectAbortedError extends DirectError { constructor(m = "aborted") { super(m); this.name = "DirectAbortedError"; } }
export class DirectTimeoutError extends DirectError { constructor(m: string) { super(m); this.name = "DirectTimeoutError"; } }
export class DirectProtocolError extends DirectError { constructor(m: string, c?: unknown) { super(m, c); this.name = "DirectProtocolError"; } }

/** Strip Bearer tokens (and bare JWT-shaped tokens) from any string before
 *  it leaves the module. Three patterns:
 *    1. `Bearer <token>` with whitespace separator — the standard header form
 *    2. `Bearer<token>` with no whitespace — broken clients / log glitches
 *    3. Bare JWT `xxx.yyy.zzz` shape, length >= 40 — defensive catch for
 *       tokens that leak via error.cause or stringified objects without the
 *       Bearer prefix. Conservative length check avoids matching version
 *       strings like `1.2.3-beta` or short hashes. */
export function redact(s: string): string {
  return s
    .replace(/Bearer\s*[A-Za-z0-9._\-]+/g, "Bearer <redacted>")
    .replace(/\b[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{20,}\b/g, "<token-redacted>");
}

// ── Headers ────────────────────────────────────────────────────────────────
// Mimic the captured HAR exactly (Chrome 148 on Windows, ar locale,
// Cairo timezone). Don't deviate without reason — the server fingerprints
// these together with the PoW signature.
function baseHeaders(token: string, extra: Record<string, string> = {}): Record<string, string> {
  return {
    accept: "*/*",
    "accept-language": "ar,en-GB;q=0.9,en-US;q=0.8,en;q=0.7",
    authorization: `Bearer ${token}`,
    "content-type": "application/json",
    origin: "https://chat.deepseek.com",
    referer: "https://chat.deepseek.com/",
    "user-agent":
      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
      "(KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36",
    "x-app-version": "2.0.0",
    "x-client-version": "2.0.0",
    "x-client-platform": "web",
    "x-client-locale": "en_US",
    "x-client-timezone-offset": "10800",
    ...extra,
  };
}

// ── PoW solver ─────────────────────────────────────────────────────────────
export interface Challenge {
  algorithm: string;
  challenge: string;
  salt: string;
  difficulty: number;
  expire_at: number;
  signature: string;
  target_path: string;
}

interface WasmExports {
  memory: WebAssembly.Memory;
  wasm_solve: (
    retptr: number,
    chal_ptr: number,
    chal_len: number,
    pref_ptr: number,
    pref_len: number,
    difficulty: number,
  ) => void;
  __wbindgen_add_to_stack_pointer: (delta: number) => number;
  __wbindgen_export_0: (len: number, align: number) => number;
}

let wasmInstance: WasmExports | null = null;

async function getWasm(): Promise<WasmExports> {
  if (wasmInstance) return wasmInstance;
  const here = dirname(fileURLToPath(import.meta.url));
  const wasmPath = join(here, "sha3_wasm.wasm");
  const bytes = await readFile(wasmPath);
  // The module declares zero imports; pass an empty import object.
  const { instance } = await WebAssembly.instantiate(bytes, {});
  wasmInstance = instance.exports as unknown as WasmExports;
  return wasmInstance;
}

function writeUtf8(exp: WasmExports, text: string): { ptr: number; len: number } {
  const bytes = new TextEncoder().encode(text);
  const ptr = exp.__wbindgen_export_0(bytes.length, 1);
  const view = new Uint8Array(exp.memory.buffer, ptr, bytes.length);
  view.set(bytes);
  return { ptr, len: bytes.length };
}

/** Solves a DeepSeekHashV1 PoW challenge and returns the base64-encoded
 *  payload to send as `x-ds-pow-response`. Exported for tests. */
export async function solveChallenge(c: Challenge): Promise<string> {
  const exp = await getWasm();
  const prefix = `${c.salt}_${c.expire_at}_`;
  const retptr = exp.__wbindgen_add_to_stack_pointer(-16);
  try {
    const chal = writeUtf8(exp, c.challenge);
    const pref = writeUtf8(exp, prefix);
    exp.wasm_solve(retptr, chal.ptr, chal.len, pref.ptr, pref.len, c.difficulty);
    // retptr layout: [i32 status @ 0..4, _ @ 4..8, f64 answer @ 8..16]
    const mem = new DataView(exp.memory.buffer);
    const status = mem.getInt32(retptr, true);
    if (status === 0) throw new DirectPowError("wasm_solve returned status=0 (no solution)");
    const answer = mem.getFloat64(retptr + 8, true);
    const payload = {
      algorithm: c.algorithm,
      challenge: c.challenge,
      salt: c.salt,
      answer: Math.trunc(answer),
      signature: c.signature,
      target_path: c.target_path,
    };
    return Buffer.from(JSON.stringify(payload)).toString("base64");
  } finally {
    exp.__wbindgen_add_to_stack_pointer(16);
  }
}

// ── REST helpers ───────────────────────────────────────────────────────────
interface ApiEnvelope<T> {
  code: number;
  msg: string;
  data: { biz_code: number; biz_msg: string; biz_data: T } | null;
}

function classifyHttp(path: string, status: number, body: string): DirectError {
  const safe = redact(body).slice(0, 300);
  if (status === 401) return new DirectAuthError(`${path} → 401 (token invalid/expired)`);
  if (status === 429) return new DirectRateLimitError(`${path} → 429 rate-limited`);
  if (status >= 500) return new DirectNetworkError(`${path} → ${status}: ${safe}`);
  return new DirectError(`${path} → HTTP ${status}: ${safe}`);
}

function classifyBiz(path: string, code: number, msg: string): DirectError {
  // Codes seen in the wild (from live testing + reverse-engineered libs):
  //   40003 - "Authorization Failed (invalid token)" → auth
  //   40100 - INVALID_TOKEN                          → auth
  //   40300 - MISSING_HEADER (x-ds-pow-response)     → PoW header missing
  //   40301 - INVALID_POW                            → PoW wrong / expired
  //   42900 - RATE_LIMIT                             → rate
  if (code === 40003 || code === 40100) return new DirectAuthError(`${path} → ${code} ${msg}`);
  if (code === 40300 || code === 40301) return new DirectPowError(`${path} → ${code} ${msg}`);
  if (code === 42900) return new DirectRateLimitError(`${path} → ${code} ${msg}`);
  return new DirectError(`${path} → code=${code} msg=${msg}`);
}

interface PostJsonOpts {
  signal?: AbortSignal;
  timeoutMs?: number;
}

async function postJson<T>(
  path: string,
  token: string,
  body: unknown,
  extraHeaders: Record<string, string> = {},
  opts: PostJsonOpts = {},
): Promise<T> {
  const ctrl = new AbortController();
  const onAbort = (): void => ctrl.abort(opts.signal?.reason);
  if (opts.signal) {
    if (opts.signal.aborted) throw new DirectAbortedError();
    opts.signal.addEventListener("abort", onAbort, { once: true });
  }
  const timer = setTimeout(
    () => ctrl.abort(new DirectTimeoutError(`${path} timed out after ${opts.timeoutMs ?? DEFAULT_TIMEOUT_MS}ms`)),
    opts.timeoutMs ?? DEFAULT_TIMEOUT_MS,
  );

  let r: Response;
  try {
    r = await fetch(BASE + path, {
      method: "POST",
      headers: baseHeaders(token, extraHeaders),
      body: JSON.stringify(body),
      signal: ctrl.signal,
    });
  } catch (e) {
    const err = e as Error & { name?: string };
    if (err.name === "AbortError") {
      throw ctrl.signal.reason instanceof DirectTimeoutError
        ? ctrl.signal.reason
        : new DirectAbortedError();
    }
    throw new DirectNetworkError(`${path} → ${err.message ?? String(err)}`, err);
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", onAbort);
  }

  const txt = await r.text();
  if (!r.ok) throw classifyHttp(path, r.status, txt);
  let env: ApiEnvelope<T>;
  try { env = JSON.parse(txt); } catch { throw new DirectProtocolError(`${path} → non-JSON: ${redact(txt).slice(0, 300)}`); }
  if (env.code !== 0) throw classifyBiz(path, env.code, env.msg);
  if (!env.data) throw new DirectProtocolError(`${path} → empty data`);
  if (env.data.biz_code !== 0) throw classifyBiz(path, env.data.biz_code, env.data.biz_msg);
  return env.data.biz_data;
}

export interface SessionOpts { signal?: AbortSignal; timeoutMs?: number; }

export async function createSession(token: string, opts: SessionOpts = {}): Promise<string> {
  const data = await postJson<{ chat_session: { id: string } }>(
    "/chat_session/create", token, { character_id: null }, {}, opts,
  );
  return data.chat_session.id;
}

export async function fetchChallenge(token: string, targetPath: string, opts: SessionOpts = {}): Promise<Challenge> {
  // ONE auto-retry on transient network failure (DNS hiccup, brief 502 from
  // edge, IPv6/IPv4 fallback racing). Real production case (session c1aukfC1):
  //   "DirectNetworkError: /chat/create_pow_challenge → fetch failed"
  //   caused the entire turn to die with no user-visible retry path. A single
  //   in-process retry recovers nearly all transient failures we've seen.
  //
  // Strict scope: only retry on `DirectNetworkError` (not abort, not biz
  // codes, not timeouts — those are not transient and deserve to fail fast).
  try {
    const data = await postJson<{ challenge: Challenge }>(
      "/chat/create_pow_challenge", token, { target_path: targetPath }, {}, opts,
    );
    return data.challenge;
  } catch (e) {
    if (!(e instanceof DirectNetworkError)) throw e;
    if (opts.signal?.aborted) throw e;
    log.warn("fetchchallenge_retry_after_network_error", {
      targetPath,
      cause: (e as Error).message,
    });
    // Short backoff — give the network 250ms to settle.
    await new Promise((r) => setTimeout(r, 250));
    const data = await postJson<{ challenge: Challenge }>(
      "/chat/create_pow_challenge", token, { target_path: targetPath }, {}, opts,
    );
    return data.challenge;
  }
}

// ── File upload (vision) ──────────────────────────────────────────────────
// DeepSeek's web protocol attaches images by uploading them first to
// /api/v0/file/upload_file (returning a file-* id) and then passing those
// ids in `ref_file_ids` on the chat/completion call. The vision-capable
// model then picks them up from the conversation context.
//
// Flow:
//   1. fetchChallenge(target_path = "/api/v0/file/upload_file")
//   2. solve PoW
//   3. POST multipart with field "file" = the image bytes
//      + headers: x-ds-pow-response, x-file-size, x-thinking-enabled, x-model-type
//   4. response: { id: "file-...", status: "PENDING", is_image: true, ... }
//   5. poll GET /api/v0/file/fetch_files?file_ids=file-...
//      until status === "SUCCESS" (or CONTENT_EMPTY for empty/non-text files)
//
// Status values seen: PENDING → PARSING → (SUCCESS | CONTENT_EMPTY | FAILED).
// CONTENT_EMPTY happens for some images (extraction yielded no text); the
// image is still attached and the model can still see it.

export interface UploadedFile {
  id: string;
  status: string;
  fileName: string;
  fileSize: number;
  isImage: boolean;
  auditResult: string;
  tokenUsage: number | null;
}

export interface UploadOpts {
  fileName: string;
  /** MIME type. Default inferred from extension or "application/octet-stream". */
  contentType?: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}

function inferMime(name: string): string {
  const ext = name.toLowerCase().split(".").pop();
  switch (ext) {
    case "png": return "image/png";
    case "jpg": case "jpeg": return "image/jpeg";
    case "gif": return "image/gif";
    case "webp": return "image/webp";
    case "pdf": return "application/pdf";
    case "txt": case "md": return "text/plain";
    default: return "application/octet-stream";
  }
}

/** Builds a multipart/form-data body for a single "file" field. Returns
 *  the body bytes and the Content-Type header (with the boundary baked in).
 *  We do this manually to avoid pulling in a FormData polyfill. */
function buildMultipart(fileBytes: Uint8Array, fileName: string, contentType: string): { body: Uint8Array; contentType: string } {
  const boundary = "----DeepPlanBoundary" + Math.random().toString(36).slice(2, 18);
  const enc = new TextEncoder();
  // Per HAR: Content-Disposition uses the original filename verbatim; UTF-8
  // is fine (the captured request used Arabic in a filename without escaping).
  const head = enc.encode(
    `--${boundary}\r\n` +
    `Content-Disposition: form-data; name="file"; filename="${fileName}"\r\n` +
    `Content-Type: ${contentType}\r\n\r\n`,
  );
  const tail = enc.encode(`\r\n--${boundary}--\r\n`);
  const body = new Uint8Array(head.length + fileBytes.length + tail.length);
  body.set(head, 0);
  body.set(fileBytes, head.length);
  body.set(tail, head.length + fileBytes.length);
  return { body, contentType: `multipart/form-data; boundary=${boundary}` };
}

export async function uploadFile(
  token: string,
  fileBytes: Uint8Array | Buffer,
  opts: UploadOpts,
): Promise<UploadedFile> {
  const release = await rateAcquire(token, opts.signal);
  try {
    // Solve PoW for the upload endpoint specifically. The server rejects a
    // PoW signed for /chat/completion if you reuse it here.
    const challenge = await fetchChallenge(token, "/api/v0/file/upload_file", {
      signal: opts.signal, timeoutMs: opts.timeoutMs,
    });
    const pow = await solveChallenge(challenge);

    const bytes = fileBytes instanceof Buffer ? new Uint8Array(fileBytes) : fileBytes;
    const ct = opts.contentType ?? inferMime(opts.fileName);
    const { body, contentType: bodyCT } = buildMultipart(bytes, opts.fileName, ct);

    // Extra headers the web client sends on every upload.
    const extra: Record<string, string> = {
      "content-type": bodyCT,
      "x-ds-pow-response": pow,
      "x-file-size": String(bytes.length),
      "x-thinking-enabled": "0",
      "x-model-type": "default",
    };
    // Strip default content-type (application/json) from baseHeaders.
    const headers = baseHeaders(token, extra);

    const ctrl = new AbortController();
    const onAbort = (): void => ctrl.abort(opts.signal?.reason);
    if (opts.signal) {
      if (opts.signal.aborted) throw new DirectAbortedError();
      opts.signal.addEventListener("abort", onAbort, { once: true });
    }
    const timer = setTimeout(
      () => ctrl.abort(new DirectTimeoutError(`upload_file timed out after ${opts.timeoutMs ?? DEFAULT_TIMEOUT_MS}ms`)),
      opts.timeoutMs ?? DEFAULT_TIMEOUT_MS,
    );

    let r: Response;
    try {
      r = await fetch(BASE + "/file/upload_file", {
        method: "POST", headers, body: body as BodyInit, signal: ctrl.signal,
      });
    } catch (e) {
      const err = e as Error & { name?: string };
      if (err.name === "AbortError") {
        throw ctrl.signal.reason instanceof DirectTimeoutError ? ctrl.signal.reason : new DirectAbortedError();
      }
      throw new DirectNetworkError(`upload_file → ${err.message ?? String(err)}`, err);
    } finally {
      clearTimeout(timer);
      opts.signal?.removeEventListener("abort", onAbort);
    }

    const txt = await r.text();
    if (!r.ok) throw classifyHttp("/file/upload_file", r.status, txt);
    const env = JSON.parse(txt) as ApiEnvelope<{
      id: string; status: string; file_name: string; file_size: number;
      is_image: boolean; audit_result: string; token_usage: number | null;
    }>;
    if (env.code !== 0) throw classifyBiz("/file/upload_file", env.code, env.msg);
    if (!env.data || env.data.biz_code !== 0) throw classifyBiz("/file/upload_file", env.data?.biz_code ?? -1, env.data?.biz_msg ?? "no data");
    const d = env.data.biz_data;
    return {
      id: d.id, status: d.status, fileName: d.file_name, fileSize: d.file_size,
      isImage: d.is_image, auditResult: d.audit_result, tokenUsage: d.token_usage,
    };
  } finally {
    release();
  }
}

export interface WaitFileOpts {
  signal?: AbortSignal;
  /** Total budget. Default 60s — large images can take ~5–15s to parse. */
  timeoutMs?: number;
  /** Poll interval. Default 800ms. */
  pollIntervalMs?: number;
}

/**
 * Poll fetch_files until the file leaves PENDING/PARSING.
 * Returns the final file record (success or failure).
 * Throws DirectTimeoutError if the budget runs out.
 */
export async function waitForFile(token: string, fileId: string, opts: WaitFileOpts = {}): Promise<UploadedFile> {
  const deadline = Date.now() + (opts.timeoutMs ?? 60_000);
  const interval = opts.pollIntervalMs ?? 800;
  for (;;) {
    if (opts.signal?.aborted) throw new DirectAbortedError();
    if (Date.now() > deadline) throw new DirectTimeoutError(`waitForFile(${fileId}) timed out`);

    const r = await fetch(BASE + `/file/fetch_files?file_ids=${encodeURIComponent(fileId)}`, {
      method: "GET", headers: baseHeaders(token), signal: opts.signal,
    });
    const txt = await r.text();
    if (!r.ok) throw classifyHttp("/file/fetch_files", r.status, txt);
    const env = JSON.parse(txt) as ApiEnvelope<{ files: Array<{
      id: string; status: string; file_name: string; file_size: number;
      is_image: boolean; audit_result: string; token_usage: number | null;
    }> }>;
    if (env.code !== 0) throw classifyBiz("/file/fetch_files", env.code, env.msg);
    const f = env.data?.biz_data?.files?.[0];
    if (!f) throw new DirectProtocolError(`fetch_files returned no file for ${fileId}`);

    const terminal = f.status !== "PENDING" && f.status !== "PARSING";
    if (terminal) {
      return {
        id: f.id, status: f.status, fileName: f.file_name, fileSize: f.file_size,
        isImage: f.is_image, auditResult: f.audit_result, tokenUsage: f.token_usage,
      };
    }
    await new Promise<void>((resolve, reject) => {
      const t = setTimeout(resolve, interval);
      opts.signal?.addEventListener("abort", () => { clearTimeout(t); reject(new DirectAbortedError()); }, { once: true });
    });
  }
}

// ── SSE parser (pure, no I/O — fixture-testable) ──────────────────────────
//
// The DeepSeek web protocol is a custom JSON-Patch stream, not OpenAI-style.
//
//   First payload  : { v: { response: { fragments: [{ id, type, content, ... }, ...] } } }
//                    → seed every fragment's accumulated text by id (the
//                      seeded `content` is the FIRST output token).
//   Full patch     : { p: "response/fragments/-1/content", o: "APPEND", v: "ه" }
//                    → append v to the LAST fragment's text (-1 = last).
//   Shorthand      : { v: "لاً" }
//                    → continuation of the previous patch (same p, same o).
//                      The web client carries `p`/`o` forward implicitly
//                      until a new full patch resets them. ~95% of payload
//                      bytes are saved this way.
//   Status patches : { p: "response/status", o: "SET", v: "FINISHED" }
//   Batch ops      : { p: "response", o: "BATCH", v: [{p, v}, ...] }
//   `event: close` : terminal event after FINISHED
//
// Fragment types we've seen: "RESPONSE" (visible answer), and (for thinking
// mode) "THINKING". We route by fragment type → text vs reasoning.
export interface ParserCallbacks {
  onChunk?: (text: string) => void;
  onReasoning?: (text: string) => void;
}

export interface ParserState {
  text: string;
  reasoning: string;
  finishReason: string | null;
  closed: boolean;
  /** From `event: ready` — needed for chaining continuation turns via parent_message_id. */
  requestMessageId: number | null;
  responseMessageId: number | null;
}

export function createParser(cb: ParserCallbacks = {}): {
  feed: (s: string) => void;
  state: ParserState;
} {
  const state: ParserState = {
    text: "", reasoning: "", finishReason: null, closed: false,
    requestMessageId: null, responseMessageId: null,
  };
  const fragments = new Map<number, { type: string }>();
  const fragOrder: number[] = [];
  let lastFragId: number | null = null;
  let lastOp: string | null = null;
  let buf = "";

  function emit(id: number, piece: string): void {
    const frag = fragments.get(id);
    if (!frag || !piece) return;
    if (frag.type === "THINKING" || frag.type === "REASONING") {
      state.reasoning += piece;
      cb.onReasoning?.(piece);
    } else {
      state.text += piece;
      cb.onChunk?.(piece);
    }
  }

  function seed(id: number, type: string, content: string): void {
    if (!fragments.has(id)) {
      fragments.set(id, { type });
      fragOrder.push(id);
    }
    if (content) emit(id, content);
  }

  function resolveFrag(p: string): number | null {
    const m = p.match(/response\/fragments\/(-?\d+)\/content/);
    if (!m) return null;
    const idx = Number(m[1]);
    if (Number.isNaN(idx) || fragOrder.length === 0) return null;
    const real = idx < 0 ? fragOrder.length + idx : idx;
    return real >= 0 && real < fragOrder.length ? fragOrder[real] : null;
  }

  function applyPatch(j: { p?: string; o?: string; v?: unknown }): void {
    if (j.p === "response/status" && j.o === "SET" && typeof j.v === "string") {
      if (j.v === "FINISHED") state.finishReason = "stop";
      else if (j.v === "INTERRUPTED") state.finishReason = "interrupted";
      return;
    }
    if (typeof j.p === "string" && /response\/fragments\/-?\d+\/content/.test(j.p)) {
      const id = resolveFrag(j.p);
      if (id !== null && j.o === "APPEND" && typeof j.v === "string") {
        emit(id, j.v);
        lastFragId = id;
        lastOp = "APPEND";
      }
      return;
    }
    if (j.p === "response" && j.o === "BATCH" && Array.isArray(j.v)) {
      for (const sub of j.v as Array<{ p?: string; o?: string; v?: unknown }>) {
        if (sub && typeof sub === "object" && sub.p) applyPatch(sub);
      }
    }
  }

  function feed(s: string): void {
    if (state.closed) return;
    buf += s;
    let nl: number;
    while ((nl = buf.indexOf("\n\n")) >= 0) {
      const ev = buf.slice(0, nl);
      buf = buf.slice(nl + 2);
      let eventType: string | null = null;
      for (const line of ev.split("\n")) {
        if (line.startsWith("event: ")) { eventType = line.slice(7).trim(); continue; }
        if (!line.startsWith("data: ")) continue;
        const data = line.slice(6);
        if (data === "[DONE]") { state.finishReason = state.finishReason ?? "stop"; continue; }
        let j: unknown;
        try { j = JSON.parse(data); } catch { continue; }
        if (!j || typeof j !== "object") continue;
        const obj = j as Record<string, unknown>;

        // event: ready carries request/response message IDs we need to thread
        // continuation turns (parent_message_id = responseMessageId of prev).
        if (eventType === "ready") {
          if (typeof obj.request_message_id === "number") state.requestMessageId = obj.request_message_id;
          if (typeof obj.response_message_id === "number") state.responseMessageId = obj.response_message_id;
          continue;
        }

        // First-message snapshot: { v: { response: { fragments: [...] } } }
        if (obj.v && typeof obj.v === "object" && !("p" in obj)) {
          const resp = (obj.v as Record<string, unknown>).response as Record<string, unknown> | undefined;
          if (resp && Array.isArray(resp.fragments)) {
            for (const f of resp.fragments as Array<Record<string, unknown>>) {
              if (typeof f.id === "number" && typeof f.type === "string") {
                seed(f.id, f.type, typeof f.content === "string" ? f.content : "");
                lastFragId = f.id;
                lastOp = "APPEND";
              }
            }
            continue;
          }
        }

        // Shorthand continuation
        if (!("p" in obj) && typeof obj.v === "string" && lastFragId !== null && lastOp === "APPEND") {
          emit(lastFragId, obj.v);
          continue;
        }

        if (typeof obj.p === "string") applyPatch(obj as { p: string; o?: string; v?: unknown });
      }
      if (eventType === "close") { state.closed = true; return; }
    }
  }

  return { feed, state };
}

// ── Streaming completion ───────────────────────────────────────────────────
export interface CompletionOpts {
  token: string;
  sessionId: string;
  prompt: string;
  parentMessageId?: string | number | null;
  thinkingEnabled?: boolean;
  searchEnabled?: boolean;
  /** File IDs from uploadFile() to attach to this turn (vision/docs). */
  refFileIds?: string[];
  onChunk?: (text: string) => void;
  onReasoning?: (text: string) => void;
  signal?: AbortSignal;
  /** Per-call timeout in ms. Applies to each REST step + the SSE stream as a whole. */
  timeoutMs?: number;
}

export interface CompletionResult {
  text: string;
  reasoning: string;
  finishReason: string | null;
  latencyMs: number;
  requestMessageId: number | null;
  responseMessageId: number | null;
  /** True when stream ended without a clean "stop" finish. Caller should
   *  treat it as truncated and may continue via parent_message_id chaining. */
  truncated: boolean;
}

export async function completion(opts: CompletionOpts): Promise<CompletionResult> {
  const t0 = Date.now();
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  // Steps 1-2: challenge + solve. These are short-lived and share the
  // outer signal but each has its own per-call timeout.
  const challenge = await fetchChallenge(opts.token, "/api/v0/chat/completion", {
    signal: opts.signal, timeoutMs,
  });
  const pow = await solveChallenge(challenge);

  // Step 3: SSE stream. Wire abort + timeout to the same controller.
  const ctrl = new AbortController();
  const onAbort = (): void => ctrl.abort(opts.signal?.reason);
  if (opts.signal) {
    if (opts.signal.aborted) throw new DirectAbortedError();
    opts.signal.addEventListener("abort", onAbort, { once: true });
  }
  const timer = setTimeout(
    () => ctrl.abort(new DirectTimeoutError(`completion stream timed out after ${timeoutMs}ms`)),
    timeoutMs,
  );

  let r: Response;
  try {
    r = await fetch(BASE + "/chat/completion", {
      method: "POST",
      headers: baseHeaders(opts.token, { "x-ds-pow-response": pow }),
      body: JSON.stringify({
        chat_session_id: opts.sessionId,
        parent_message_id: opts.parentMessageId ?? null,
        prompt: opts.prompt,
        ref_file_ids: opts.refFileIds ?? [],
        thinking_enabled: opts.thinkingEnabled ?? false,
        search_enabled: opts.searchEnabled ?? false,
      }),
      signal: ctrl.signal,
    });
  } catch (e) {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", onAbort);
    const err = e as Error & { name?: string };
    if (err.name === "AbortError") {
      throw ctrl.signal.reason instanceof DirectTimeoutError
        ? ctrl.signal.reason
        : new DirectAbortedError();
    }
    throw new DirectNetworkError(`completion → ${err.message ?? String(err)}`, err);
  }

  if (!r.ok) {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", onAbort);
    const body = await r.text();
    try {
      const env = JSON.parse(body) as ApiEnvelope<unknown>;
      if (env.code !== 0) throw classifyBiz("/chat/completion", env.code, env.msg);
    } catch (parseErr) {
      if (parseErr instanceof DirectError) throw parseErr;
    }
    throw classifyHttp("/chat/completion", r.status, body);
  }

  // Important: PoW errors (40300/40301) come back as 200 OK with a JSON envelope
  // body, NOT as SSE. We must detect this BEFORE trying to read the body as a
  // stream — otherwise the parser silently produces empty output and the caller
  // sees a "successful but blank" response instead of a classified error.
  const contentType = (r.headers.get("content-type") || "").toLowerCase();
  if (!contentType.includes("event-stream")) {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", onAbort);
    const body = await r.text();
    try {
      const env = JSON.parse(body) as ApiEnvelope<unknown>;
      if (env.code !== 0) throw classifyBiz("/chat/completion", env.code, env.msg);
    } catch (parseErr) {
      if (parseErr instanceof DirectError) throw parseErr;
    }
    throw new DirectProtocolError(
      `completion → expected event-stream, got ${contentType}: ${redact(body).slice(0, 300)}`,
    );
  }

  if (!r.body) throw new DirectProtocolError("completion → no response body stream");

  const parser = createParser({ onChunk: opts.onChunk, onReasoning: opts.onReasoning });
  const reader = r.body.getReader();
  const dec = new TextDecoder();
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      parser.feed(dec.decode(value, { stream: true }));
      if (parser.state.closed) break;
    }
  } catch (e) {
    const err = e as Error & { name?: string };
    if (err.name === "AbortError") {
      throw ctrl.signal.reason instanceof DirectTimeoutError
        ? ctrl.signal.reason
        : new DirectAbortedError();
    }
    throw new DirectNetworkError(`completion stream → ${err.message ?? String(err)}`, err);
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener("abort", onAbort);
  }

  return {
    text: parser.state.text,
    reasoning: parser.state.reasoning,
    finishReason: parser.state.finishReason,
    latencyMs: Date.now() - t0,
    requestMessageId: parser.state.requestMessageId,
    responseMessageId: parser.state.responseMessageId,
    truncated: parser.state.finishReason !== "stop" || !parser.state.closed,
  };
}

// ── Per-token rate limiter ────────────────────────────────────────────────
// Goal: prevent ourselves from getting 429-ed by accident. Two knobs:
//   - max concurrent in-flight per token (default 2)
//   - min interval between request *starts* (default 250 ms)
// Both are conservative for the chat.deepseek.com web rate limits we've seen.
//
// Keyed by token (truncated) so multi-account rotation is naturally isolated.
// In-process only — won't help across multiple Node workers, but the bridge
// model is single-process anyway.
interface RateState {
  inFlight: number;
  lastStart: number;
  queue: Array<() => void>;
}
const rateMap = new Map<string, RateState>();
const RATE_MAX_CONCURRENT = 2;
const RATE_MIN_INTERVAL_MS = 250;

function rateKey(token: string): string { return token.slice(0, 24); }

async function rateAcquire(token: string, signal?: AbortSignal): Promise<() => void> {
  const k = rateKey(token);
  const r = rateMap.get(k) ?? { inFlight: 0, lastStart: 0, queue: [] };
  if (!rateMap.has(k)) rateMap.set(k, r);

  // Wait for a slot
  while (r.inFlight >= RATE_MAX_CONCURRENT) {
    if (signal?.aborted) throw new DirectAbortedError();
    await new Promise<void>((resolve) => {
      const cb = (): void => { signal?.removeEventListener("abort", onAbort); resolve(); };
      const onAbort = (): void => { const i = r.queue.indexOf(cb); if (i >= 0) r.queue.splice(i, 1); cb(); };
      r.queue.push(cb);
      signal?.addEventListener("abort", onAbort, { once: true });
    });
  }
  if (signal?.aborted) throw new DirectAbortedError();

  // Min interval between starts
  const wait = Math.max(0, r.lastStart + RATE_MIN_INTERVAL_MS - Date.now());
  if (wait > 0) {
    await new Promise<void>((resolve, reject) => {
      const t = setTimeout(resolve, wait);
      signal?.addEventListener("abort", () => { clearTimeout(t); reject(new DirectAbortedError()); }, { once: true });
    });
  }

  r.inFlight++;
  r.lastStart = Date.now();
  return () => {
    r.inFlight--;
    const next = r.queue.shift();
    if (next) next();
  };
}

// ── completion() with PoW retry on 40301 ──────────────────────────────────
// Wraps the inner completion call so that an expired challenge (which the
// server rejects with code 40301 between solve and send) is recovered
// transparently with one fresh challenge fetch.
const _completionInner = completion;

export async function completionWithRetry(opts: CompletionOpts): Promise<CompletionResult> {
  const release = await rateAcquire(opts.token, opts.signal);
  try {
    try {
      return await _completionInner(opts);
    } catch (e) {
      if (e instanceof DirectPowError) {
        // One retry: fetchChallenge + solve happens inside completion() so
        // calling it again gets a fresh challenge automatically.
        return await _completionInner(opts);
      }
      throw e;
    }
  } finally {
    release();
  }
}

// ── chat(): auto-continue across truncations ──────────────────────────────
//
// Problem: long answers get cut off — by length cap, network hiccup, or the
// server closing the stream before "FINISHED". Restarting from scratch wastes
// the partial work. This wrapper:
//
//   1. Sends the user's prompt (turn 0).
//   2. Captures the response_message_id.
//   3. If finishReason !== "stop", sends a SHORT continuation prompt threaded
//      via parent_message_id. The model has full context (same session) and
//      picks up where it left off.
//   4. Repeats up to maxContinuations.
//   5. Concatenates streamed text. The caller's onChunk fires for every piece
//      across all turns — caller sees one continuous stream.
//
// Why this works: the DeepSeek session preserves the in-progress assistant
// message on the server side. By chaining a new turn with parent_message_id =
// previous response_message_id, the next answer starts where the previous
// stopped *in the same conversation thread*.
//
// Caveats:
//   - The model may add a leading space or punctuation on continuation. We
//     accept that — it's better than restart-from-scratch and usually invisible.
//   - If the model interprets "continue" as "summarize what you had" instead
//     of "keep writing", you'll see a regression. The default Arabic prompt
//     is phrased to minimize that, but tune via continuePrompt if you see it.
const DEFAULT_CONTINUE_PROMPT_AR =
  "تابع من النقطة التي توقفت عندها بالضبط، حرفياً. لا تكرر ما كتبت سابقاً. لا تبدأ من جديد. لا تلخص. أكمل الكتابة من الكلمة التالية مباشرة كأنك لم تتوقف.";

export interface ChatOpts extends Omit<CompletionOpts, "onChunk" | "onReasoning"> {
  /** Default true. When false, behaves like completion() — single turn, no auto-continue. */
  autoContinue?: boolean;
  /** Hard cap on continuation turns. Default 6 (≈ 7 total turns). */
  maxContinuations?: number;
  /** Custom continuation prompt. Defaults to an Arabic prompt that minimizes restart/summarize behavior. */
  continuePrompt?: string;
  /** Streamed for every piece across ALL turns. Caller sees one continuous stream. */
  onChunk?: (text: string) => void;
  onReasoning?: (text: string) => void;
  /** Fired once before each continuation turn. n=1 means first continuation. */
  onContinuation?: (n: number, reason: string) => void;
}

export interface ChatResult {
  text: string;
  reasoning: string;
  /** "stop" if a turn finished cleanly; "max_continuations" if we ran out of retries. */
  finishReason: string;
  /** Number of continuation turns *after* the first turn. 0 = single shot. */
  continuations: number;
  /** response_message_id of the LAST turn (use for next user message). */
  finalMessageId: number | null;
  totalLatencyMs: number;
  /** Per-turn breakdown for diagnostics. */
  turns: Array<{ turn: number; chars: number; latencyMs: number; finishReason: string | null; truncated: boolean }>;
}

export async function chat(opts: ChatOpts): Promise<ChatResult> {
  const t0 = Date.now();
  // Default lowered 6 → 4. The previous 6-cap meant up to 7 turns total, and
  // when a model genuinely stalls (same text every continuation) we'd waste
  // ~7× the tokens before bailing. Stalled-output detection below adds a
  // second brake so most stuck loops exit in 2–3 turns regardless.
  const max = opts.maxContinuations ?? 4;
  const autoContinue = opts.autoContinue ?? true;
  const continuePrompt = opts.continuePrompt ?? DEFAULT_CONTINUE_PROMPT_AR;

  let parentId: string | number | null = opts.parentMessageId ?? null;
  let totalText = "";
  let totalReasoning = "";
  const turns: ChatResult["turns"] = [];
  // Tail of the previous turn's text. If a continuation produces an output
  // identical (or near-identical) to the prior tail, the model is looping —
  // exit early rather than burning more tokens reproducing the same text.
  let prevTail = "";

  for (let turn = 0; turn <= max; turn++) {
    if (opts.signal?.aborted) throw new DirectAbortedError();

    const prompt = turn === 0 ? opts.prompt : continuePrompt;
    if (turn > 0) {
      const prev = turns[turn - 1];
      const reason = prev?.finishReason ?? (prev?.truncated ? "truncated" : "unknown");
      opts.onContinuation?.(turn, reason);
    }

    const result = await completionWithRetry({
      token: opts.token,
      sessionId: opts.sessionId,
      prompt,
      parentMessageId: parentId,
      thinkingEnabled: opts.thinkingEnabled,
      searchEnabled: opts.searchEnabled,
      refFileIds: turn === 0 ? opts.refFileIds : undefined,
      signal: opts.signal,
      timeoutMs: opts.timeoutMs,
      onChunk: opts.onChunk,
      onReasoning: opts.onReasoning,
    });

    totalText += result.text;
    totalReasoning += result.reasoning;
    parentId = result.responseMessageId;
    turns.push({
      turn, chars: result.text.length, latencyMs: result.latencyMs,
      finishReason: result.finishReason, truncated: result.truncated,
    });

    if (!result.truncated) {
      return { text: totalText, reasoning: totalReasoning, finishReason: "stop",
               continuations: turn, finalMessageId: parentId, totalLatencyMs: Date.now() - t0, turns };
    }
    if (!autoContinue) {
      return { text: totalText, reasoning: totalReasoning, finishReason: result.finishReason ?? "truncated",
               continuations: turn, finalMessageId: parentId, totalLatencyMs: Date.now() - t0, turns };
    }

    // Stall detector — same content as last turn means we're looping. Compare
    // the last 200 chars of each tail; if 90%+ overlap, give up early.
    const tail = result.text.slice(-200);
    if (turn > 0 && prevTail && tailsOverlap(prevTail, tail)) {
      return {
        text: totalText, reasoning: totalReasoning, finishReason: "stalled",
        continuations: turn, finalMessageId: parentId, totalLatencyMs: Date.now() - t0, turns,
      };
    }
    prevTail = tail;
  }

  return {
    text: totalText, reasoning: totalReasoning, finishReason: "max_continuations",
    continuations: max, finalMessageId: parentId as number | null, totalLatencyMs: Date.now() - t0, turns,
  };
}

/** Returns true when two tails are ≥90% identical (loose substring match) —
 *  the cheapest test that catches "model regenerates the same paragraph". */
function tailsOverlap(a: string, b: string): boolean {
  if (a.length < 50 || b.length < 50) return false;
  const shorter = a.length < b.length ? a : b;
  const longer = a.length < b.length ? b : a;
  const sample = shorter.slice(0, Math.floor(shorter.length * 0.9));
  return longer.includes(sample);
}
